# while loop
count = 0
while count < 5:
    print(count)
    count += 1
# 0, 1, 2, 3, 4

# break — exit loop early
for i in range(10):
    if i == 5:
        break
    print(i)          # 0, 1, 2, 3, 4

# continue — skip current iteration
for i in range(10):
    if i % 2 == 0:
        continue      # skip even numbers
    print(i)          # 1, 3, 5, 7, 9

# Searching with for-else (unique Python pattern!)
numbers = [3, 7, 2, 9, 4]
target = 99

for n in numbers:
    if n == target:
        print(f'Found {target}!')
        break
else:
    print(f'{target} not found')   # runs if no break
# → 99 not found
